object Main {
  def main(args: Array[String]): Unit = {
    val line = scala.io.StdIn.readLine()
    val parts = line.split(" ")
    val a = parts(0).toInt
    val b = parts(1).toInt
    def sumAbs(x: Int, y: Int): Int = {
      val absX = if (x > 0) x else -x
      val absY = if (y > 0) y else -y
      absX + absY
    }
    println(sumAbs(a, b))
  }
}

