problems.solution:
object Main {
  def main(args: Array[String]): Unit = {
    val n = scala.io.StdIn.readInt()
    val kategori = n match {
      case x if x >= 80 => "A"
      case x if x >= 70 => "B"
      case x if x >= 60 => "C"
      case x if x >= 50 => "D"
      case _            => "E"
    }
    println(kategori)
  }
}
